import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static long MOD = 998244353;
    static int MAX = 200005;
    
    
    static long arr2[] = new long[MAX];
    
    static long arr3[] = new long[MAX];
    
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		func();
		Scanner sc = new Scanner(System.in);
		
		int t  =  sc.nextInt();
		
		while(t-->0){
		    int n =  sc.nextInt();
		    int arr[] =  new int[n];
		    
		    for(int i = 0;i<n;i++){
		        arr[i] =  sc.nextInt();
		    }
		    
		    long ans = 0;
		    
		    
		    for(int i = 0;i<n;i++){
		        long coff = (arr3[i]+arr3[n-1-i])%MOD;
		        ans = (ans+arr[i]*coff)%MOD;
		    }
		    
		    System.out.println(ans);
		    
		    
		}

	}
	
	
	public static void func(){
	    arr2[1] = 1;
	    for(int i = 2;i<MAX;i++){
	        arr2[i] = MOD - (MOD/i)*arr2[(int)(MOD%i)]%MOD;
	    }
	    
	    for(int i  =1;i<MAX;i++){
	        arr3[i] = (arr3[i-1]+arr2[i])%MOD;
	    }
	}
}
